// 通用 split 函数
vector<string> split(const string& str, const string& delimiter) {
    vector<string> result;
    size_t start = 0;
    size_t end = str.find(delimiter);
    while (end != string::npos) {
        result.push_back(str.substr(start, end - start));
        start = end + delimiter.length();
        end = str.find(delimiter, start);
    }
    // 添加最后一个部分
    result.push_back(str.substr(start));
    return result;
}
​
int main() {
    // 缓存成本
    int m ;
    cin >> m;
    cin.ignore();
    string sequence, fileSize;
    getline(cin, sequence);
    getline(cin, fileSize);

    vector<string> sequenceValue = split(sequence, " ");
    vector<string> fileSizeValue = split(fileSize, " ");

    // 统计序列出现的次数
    map<int, int> fileCount;
    // 统计序列对应的文件大小
    map<int, int> fileIdSize;
    for (int i = 0; i < sequenceValue.size(); i++) {
        string id = sequenceValue[i];
        string size = fileSizeValue[i];
        int fileId = stoi(id);
        int fileSize = stoi(size);
        fileCount[fileId]++;
        fileIdSize[fileId] = fileSize;
    }

    int res = 0;
    for (auto p : fileCount) {
        int key = p.first;
        int count = p.second;
        int size = fileIdSize[key];
        // 贪心实现
        if (count * size <= size + m) {
            res += (count * size);
        } else {
            res += (size + m);
        }
    }
    cout << res;
    return 0;
}

