public class Main {
    // 通用 split 函数
    public static List<String> split(String str, String delimiter) {
        return Arrays.asList(str.split(delimiter));
    }
​
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // 读取缓存成本
        int m = Integer.parseInt(scanner.nextLine().trim());
        String sequence = scanner.nextLine().trim();
        String fileSize = scanner.nextLine().trim();
        scanner.close();

        List<String> sequenceValue = split(sequence, " ");
        List<String> fileSizeValue = split(fileSize, " ");

        // 统计序列出现的次数
        Map<Integer, Integer> fileCount = new HashMap<>();
        // 统计序列对应的文件大小
        Map<Integer, Integer> fileIdSize = new HashMap<>();

        for (int i = 0; i < sequenceValue.size(); i++) {
            int fileId = Integer.parseInt(sequenceValue.get(i));
            int fileSizeVal = Integer.parseInt(fileSizeValue.get(i));
            fileCount.put(fileId, fileCount.getOrDefault(fileId, 0) + 1);
            fileIdSize.put(fileId, fileSizeVal);
        }

        int res = 0;
        for (Map.Entry<Integer, Integer> entry : fileCount.entrySet()) {
            int key = entry.getKey();
            int count = entry.getValue();
            int size = fileIdSize.get(key);

            // 贪心实现
            if (count * size <= size + m) {
                res += (count * size);
            } else {
                res += (size + m);
            }
        }

        System.out.println(res);
    }
}

