​
rl.on('line', (line) => {
    inputLines.push(line.trim());
    if (inputLines.length === 3) {
        rl.close();
    }
});
​
rl.on('close', () => {
    const m = parseInt(inputLines[0]);
    const sequenceValue = inputLines[1].split(" ");
    const fileSizeValue = inputLines[2].split(" ");
​
    let fileCount = new Map();
    let fileIdSize = new Map();
​
    for (let i = 0; i < sequenceValue.length; i++) {
        let fileId = parseInt(sequenceValue[i]);
        let fileSize = parseInt(fileSizeValue[i]);
        fileCount.set(fileId, (fileCount.get(fileId) || 0) + 1);
        fileIdSize.set(fileId, fileSize);
    }
​
    let res = 0;
    for (let [key, count] of fileCount) {
        let size = fileIdSize.get(key);
        if (count * size <= size + m) {
            res += count * size;
        } else {
            res += size + m;
        }
    }
