package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
​
    // 读取输入
    scanner.Scan()
    m, _ := strconv.Atoi(scanner.Text())
​
    scanner.Scan()
    f := convertToIntSlice(strings.Split(scanner.Text(), " "))
​
    scanner.Scan()
    s := convertToIntSlice(strings.Split(scanner.Text(), " "))
​
    fmt.Println(getResult(m, f, s))
}
​
func convertToIntSlice(input []string) []int {
    result := make([]int, len(input))
    for i, str := range input {
        result[i], _ = strconv.Atoi(str)
    }
    return result
}
​
func getResult(m int, f, s []int) int {
    // count 保存每个文件的出现次数
    count := make(map[int]int)
    // size 保存文件的大小
    size := make(map[int]int)
​
    for i := 0; i < len(f); i++ {
        k := f[i]
        count[k]++
        if _, exists := size[k]; !exists {
            size[k] = s[i]
        }
    }
​
    ans := 0
    for k := range count {
        // 选择每次重新扫描的成本 和 扫描一次 + 缓存的成本 中的最小值
        ans += min(count[k]*size[k], size[k]+m)
    }
​
    return ans
}
​
func min(a, b int) int {
    if a < b {
        return a
    }
    return b
}
